#[test]
fn in_unit_and_auto_unit_round_trip() {
    for v in [1e-9, 0.5, 1.0, 1234.5, 1e7, -3e4] {
        let q = WarpingMomentOfInertia::from_base(v);
        let auto = q.auto_unit();
        assert_close(
            WarpingMomentOfInertia::new(auto.value, auto.unit).as_base(),
            v,
            F64_TOL,
        );
        for &unit in WarpingMomentOfInertiaUnit::ALL {
            let shown = q.in_unit(unit);
            assert_eq!((shown.value, shown.unit), (q.convert_to(unit), unit));
        }
    }
    assert_eq!(
        WarpingMomentOfInertia::from_base(0.0).auto_unit().unit,
        WarpingMomentOfInertiaUnit::MeterToTheSixth
    );
}

#[test]
fn parse_every_abbreviation() {
    assert_eq!(
        "m⁶".parse::<WarpingMomentOfInertiaUnit>(),
        Ok(WarpingMomentOfInertiaUnit::MeterToTheSixth)
    );
    assert_eq!(
        format!("2.5 {}", "m⁶").parse::<WarpingMomentOfInertia>(),
        Ok(WarpingMomentOfInertia::new(
            2.5,
            WarpingMomentOfInertiaUnit::MeterToTheSixth
        ))
    );
    assert_eq!(
        "dm⁶".parse::<WarpingMomentOfInertiaUnit>(),
        Ok(WarpingMomentOfInertiaUnit::DecimeterToTheSixth)
    );
    assert_eq!(
        format!("2.5 {}", "dm⁶").parse::<WarpingMomentOfInertia>(),
        Ok(WarpingMomentOfInertia::new(
            2.5,
            WarpingMomentOfInertiaUnit::DecimeterToTheSixth
        ))
    );
    assert_eq!(
        "cm⁶".parse::<WarpingMomentOfInertiaUnit>(),
        Ok(WarpingMomentOfInertiaUnit::CentimeterToTheSixth)
    );
    assert_eq!(
        format!("2.5 {}", "cm⁶").parse::<WarpingMomentOfInertia>(),
        Ok(WarpingMomentOfInertia::new(
            2.5,
            WarpingMomentOfInertiaUnit::CentimeterToTheSixth
        ))
    );
    assert_eq!(
        "mm⁶".parse::<WarpingMomentOfInertiaUnit>(),
        Ok(WarpingMomentOfInertiaUnit::MillimeterToTheSixth)
    );
    assert_eq!(
        format!("2.5 {}", "mm⁶").parse::<WarpingMomentOfInertia>(),
        Ok(WarpingMomentOfInertia::new(
            2.5,
            WarpingMomentOfInertiaUnit::MillimeterToTheSixth
        ))
    );
    assert_eq!(
        "ft⁶".parse::<WarpingMomentOfInertiaUnit>(),
        Ok(WarpingMomentOfInertiaUnit::FootToTheSixth)
    );
    assert_eq!(
        format!("2.5 {}", "ft⁶").parse::<WarpingMomentOfInertia>(),
        Ok(WarpingMomentOfInertia::new(
            2.5,
            WarpingMomentOfInertiaUnit::FootToTheSixth
        ))
    );
    assert_eq!(
        "in⁶".parse::<WarpingMomentOfInertiaUnit>(),
        Ok(WarpingMomentOfInertiaUnit::InchToTheSixth)
    );
    assert_eq!(
        format!("2.5 {}", "in⁶").parse::<WarpingMomentOfInertia>(),
        Ok(WarpingMomentOfInertia::new(
            2.5,
            WarpingMomentOfInertiaUnit::InchToTheSixth
        ))
    );
    assert_eq!(
        "1 not-a-unit".parse::<WarpingMomentOfInertia>(),
        Err(ParseError::UnknownUnit)
    );
}

